-- 978 — E3 Undergraduate ----------------------------------------------------------------------
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (978, 'Undergraduate E3 Balanced Solutions for a Better World Scholarship', 'Trinity College Dublin', 'Ireland', 'Tuition Credit', 0, 'Three application batches for 2027/28 entry: Batch 1 closes 1 February 2027 (announced 1 March 2027), Batch 2 closes 15 March 2027 (announced 15 April 2027), Batch 3 closes 1 May 2027 (announced 31 May 2027); applications received after 1 May 2027 are assessed on a rolling basis depending on budget availability. You must already hold an offer letter for first-year entry to an eligible E3 undergraduate programme-apply for the earliest batch you can.', '2027-02-01', 'fixed', NULL, NULL, $j$["Bachelor's"]$j$, $j$["First-year entry to the listed E3 undergraduate programmes at Trinity College Dublin: BAI Engineering, BSc (Ing) Engineering with Management, B.A. Biological and Biomedical Science, B.A. Geography and Geoscience, B.A. Computer Science (incl. Computer Science and Business, Computer Science Linguistics and a Language, and Joint Honours Computer Science with Geography/Economics/Linguistics), Management Science and Information Systems Studies, BSc Environmental Science and Engineering"]$j$, $j$["Applicants with non-EU status who will pay tuition fees at the non-EU rate and hold an offer letter for first-year entry to an eligible programme"]$j$, NULL, NULL, false, true, $desc$The Undergraduate E3 Balanced Solutions for a Better World Scholarship is Trinity College Dublin's entrance award for the E3 initiative - the university's 'Engineering, Emerging Technologies and Environment' collaboration across engineering, computer science and the natural sciences. The scholarships are 1-year awards valued between EUR 2,000 and EUR 5,000 each, applied as a reduction to tuition fees: a useful discount against the non-EU first-year fee rather than full funding. They are open to applicants who have non-EU status, will pay fees at the non-EU rate, and hold an offer letter for first-year entry into one of the listed E3 undergraduate programmes - Engineering (BAI and Engineering with Management), Biological and Biomedical Science, Geography and Geoscience, Computer Science in its single- and joint-honours forms, Management Science and Information Systems Studies, and Environmental Science and Engineering. Selection is based on academic achievement and an evaluation of your potential to contribute to the E3 initiative and its broad activities, captured in a 200-word statement titled 'How I will contribute to the E3 Initiative and provide Balanced Solutions for a Better World at Trinity College Dublin' submitted through the scholarship application form. Applications run in three batches for 2027/28 entry - closing 1 February, 15 March and 1 May 2027 with announcements about a month later - and anything submitted after 1 May 2027 is assessed on a rolling basis depending on budget availability, so the earlier batches are the safer bet. The E3 Recruitment and Admissions Team tells you if you have been selected and explains how to formally accept; a parallel Postgraduate E3 scholarship exists for taught master's offer-holders (record 979), and Trinity's Global Excellence scheme (record 345) excludes these disciplines precisely because this E3 route covers them.$desc$, $req$Hold an offer letter for first-year entry to one of the eligible E3 undergraduate programmes listed on the scheme page, have non-EU status and be liable for tuition fees at the non-EU rate. Apply through the scholarship application form linked at the top of the E3 scholarships page, including the required 200-word statement on 'How I will contribute to the E3 Initiative and provide Balanced Solutions for a Better World at Trinity College Dublin'. Assessment weighs academic achievement and your evaluated potential to contribute to the E3 initiative and its broad activities; results follow the batch calendar (deadlines 1 February / 15 March / 1 May 2027, announcements 1 March / 15 April / 31 May 2027), with late applications after 1 May 2027 considered on a rolling basis only if budget remains. The E3 Recruitment and Admissions Team notifies selected applicants and explains the formal acceptance process; questions go to e3.team@tcd.ie. No scheme-level GPA or IELTS cutoff is published (both belong to programme admission), so min_gpa/min_ielts are not recorded.$req$, 'https://www.tcd.ie/e3/education/scholarships/', 'https://www.tcd.ie/e3/education/scholarships/', 'https://forms.cloud.microsoft/Pages/ResponsePage.aspx?id=jb6V1Qaz9EWAZJ5bgvvlK0B8IEHdCgJBlYUqexRYBzFUNDhTUTE2STBBVlpBWkZaOFZRSzVRSDIxRC4u', 'annual', 'open', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-28 (enrichment batch 22) from Trinity College Dublin's official E3 scholarships page fetched first-hand in full the same day: the Undergraduate E3 Balanced Solutions for a Better World Scholarship offers 1-year scholarships of EUR 2,000-EUR 5,000 applied as a reduction to tuition fees; eligible majors are BAI Engineering, BSc (Ing) Engineering with Management, B.A. Biological and Biomedical Science, B.A. Geography and Geoscience, B.A. Computer Science, B.A. Computer Science and Business, B.A. Computer Science, Linguistics and Language, Management Science and Information Systems Studies, Joint Honours Computer Science and Geography, Joint Honours Computer Science and Economics, Joint Honours Computer Science and Linguistics, and BSc Environmental Science and Engineering; applicants must have non-EU status, pay fees at the non-EU rate and hold an offer letter for first-year entry; selection on academic achievement and potential to contribute to the E3 initiative, evidenced by a 200-word statement ('How I will contribute to the E3 Initiative and provide Balanced Solutions for a Better World at Trinity College Dublin') submitted via the Microsoft form linked on the page (stored as application_url); batch deadlines 1 February 2027, 15 March 2027 and 1 May 2027 with announcements 1 March, 15 April and 31 May 2027, later applications assessed on a rolling basis depending on budget availability; queries to e3.team@tcd.ie. deadline_date 2027-02-01 ('fixed') is the first batch deadline read on the page; status 'open' (the 2027/28 cycle page and application form are live). Award stored as NULL (EUR, 'one_time', 'variable') within the published EUR 2,000-5,000 band; amount_usd_value 0 (non-USD). This is the discipline-specific sibling that Trinity's Global Excellence Postgraduate scheme (record 345) points engineering, natural-science and computer-science applicants to; the Postgraduate E3 scholarship on the same page is record 979. university_id 81 (Trinity College Dublin); university_scholarships row 703 created. Linked source: 3112 (shared with record 979). Dedupe at time of adding: no prior E3/Balanced Solutions record existed; the Government of Ireland GOI-IES scheme named in pass 115 planning was found already present as record 925 and was therefore not re-added in this batch.$note$, 81, NULL, 'EUR', 'one_time', 'variable', NULL, '1-year tuition-fee reduction of EUR 2,000-EUR 5,000 for non-EU first-year entrants to listed E3 undergraduate programmes (batch deadlines 1 Feb / 15 Mar / 1 May 2027)', 'A one-year reduction of EUR 2,000-EUR 5,000 applied to first-year tuition fees - a partial discount against the non-EU fee, not full coverage.', 'No scholarship-level IELTS figure; English-language requirements belong to undergraduate programme admission.', $j$["Offer letter for first-year entry to an eligible E3 undergraduate programme", "Scholarship application form (linked from the E3 scholarships page) including a 200-word statement: 'How I will contribute to the E3 Initiative and provide Balanced Solutions for a Better World at Trinity College Dublin'"]$j$, NULL, NULL, $json$[{"batch": 1, "deadline": "2027-02-01", "announcement": "2027-03-01", "status": "open"}, {"batch": 2, "deadline": "2027-03-15", "announcement": "2027-04-15"}, {"batch": 3, "deadline": "2027-05-01", "announcement": "2027-05-31"}, {"pattern": "Applications after 1 May are assessed on a rolling basis depending on budget availability"}]$json$);

-- 979 — E3 Postgraduate -----------------------------------------------------------------------
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (979, 'Postgraduate E3 Balanced Solutions for a Better World Scholarship', 'Trinity College Dublin', 'Ireland', 'Tuition Credit', 0, 'Three application batches for 2027/28 entry: Batch 1 closes 1 February 2027 (announced 1 March 2027), Batch 2 closes 15 March 2027 (announced 15 April 2027), Batch 3 closes 1 May 2027 (announced 31 May 2027); applications received after 1 May 2027 are assessed on a rolling basis depending on budget availability. You must already hold an offer letter for an eligible taught master''s programme - apply for the earliest batch you can.', '2027-02-01', 'fixed', NULL, NULL, $j$["Master's"]$j$, $j$["Full-time taught postgraduate programmes in the School of Engineering, the School of Computer Science and Statistics, the School of Natural Sciences, and the MSc in Energy Science at Trinity College Dublin"]$j$, $j$["Applicants who hold an offer letter for a Postgraduate Taught Masters programme in the School of Engineering, the School of Computer Science and Statistics, the School of Natural Sciences or the MSc in Energy Science"]$j$, NULL, NULL, false, true, $desc$The Postgraduate E3 Balanced Solutions for a Better World Scholarship is the taught-master's counterpart of Trinity College Dublin's E3 scholarship family: several 1-year scholarships valued between EUR 2,000 and EUR 5,000 each, applied as a reduction to the tuition fees of a full-time programme. The eligible territory is precise - full-time taught postgraduate programmes in the School of Engineering, the School of Computer Science and Statistics, the School of Natural Sciences, and the MSc in Energy Science - which is exactly the territory that Trinity's Global Excellence Postgraduate Scholarships (record 345) carve out and redirect here, so for engineers, computer scientists and natural scientists this E3 scheme, not Global Excellence, is the route to apply through. Eligibility on the scheme page is stated simply: hold an offer letter for a Postgraduate Taught Masters programme in one of those schools (or the MSc in Energy Science). Selection is based on academic achievement and an evaluation of your potential to contribute to the E3 initiative and its broad activities, evidenced in the application by a 200-word statement titled 'How I will contribute to the E3 Initiative and provide Balanced Solutions for a Better World at Trinity College Dublin'. Applications are taken in three batches for 2027/28 - closing 1 February, 15 March and 1 May 2027, with announcements on 1 March, 15 April and 31 May 2027 - and submissions after 1 May 2027 are assessed on a rolling basis only as budget allows. The E3 Recruitment and Admissions Team informs selected candidates and explains how to formally accept the scholarship; undergraduates entering E3 programmes have a parallel scheme (record 978).$desc$, $req$Hold an offer letter for a Postgraduate Taught Masters programme in the School of Engineering, the School of Computer Science and Statistics, or the School of Natural Sciences, or for the MSc in Energy Science - the offer comes first, then the scholarship application. Submit the scholarship application using the form linked at the top of the E3 scholarships page, including the required 200-word statement on 'How I will contribute to the E3 Initiative and provide Balanced Solutions for a Better World at Trinity College Dublin'. Assessment is based on academic achievement and your evaluated potential to contribute to the E3 initiative and its broad activities, decided in three batches (deadlines 1 February / 15 March / 1 May 2027; announcements 1 March / 15 April / 31 May 2027), with post-1-May applications assessed on a rolling basis depending on budget availability - earlier batches are therefore safer. The E3 Recruitment and Admissions Team will inform you if you have been selected and will explain the process to formally accept; direct questions to e3.team@tcd.ie. Note that if your programme sits outside these schools, this scheme does not apply - most other taught master's programmes fall under Trinity's Global Excellence Postgraduate Scholarships instead (record 345), and Business programmes have their own route. No scheme-level GPA or IELTS cutoff is published, so min_gpa/min_ielts are not recorded.$req$, 'https://www.tcd.ie/e3/education/scholarships/', 'https://www.tcd.ie/e3/education/scholarships/', 'https://forms.cloud.microsoft/Pages/ResponsePage.aspx?id=jb6V1Qaz9EWAZJ5bgvvlK0B8IEHdCgJBlYUqexRYBzFUNDhTUTE2STBBVlpBWkZaOFZRSzVRSDIxRC4u', 'annual', 'open', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-28 (enrichment batch 22) from Trinity College Dublin's official E3 scholarships page fetched first-hand in full the same day: the Postgraduate E3 Balanced Solutions for a Better World Scholarship offers 1-year scholarships of EUR 2,000-EUR 5,000 each, applied as a reduction to the tuition fees of a full-time programme, with several scholarships available for full-time taught postgraduate programmes in the School of Engineering, the School of Computer Science and Statistics, the School of Natural Sciences, and the MSc in Energy Science; applicants must hold an offer letter for a Postgraduate Taught Masters programme in one of those areas (the page states no fee-status condition for the postgraduate scheme, unlike the undergraduate scheme, so none is recorded); selection on academic achievement and evaluated potential to contribute to the E3 initiative and its broad activities, via the Microsoft form linked on the page (stored as application_url) including a 200-word statement ('How I will contribute to the E3 Initiative and provide Balanced Solutions for a Better World at Trinity College Dublin'); batch deadlines 1 February 2027, 15 March 2027 and 1 May 2027 with announcements 1 March, 15 April and 31 May 2027, later applications assessed on a rolling basis depending on budget availability; queries to e3.team@tcd.ie. deadline_date 2027-02-01 ('fixed') is the first batch deadline; status 'open' (2027/28 cycle page and application form live). Award stored as NULL (EUR, 'one_time', 'variable') within the published band; amount_usd_value 0. This is the scheme to which the Global Excellence Postgraduate page (record 345, pass 115) redirects engineering, natural-science and computer-science applicants; the Undergraduate E3 scholarship on the same page is record 978. university_id 81 (Trinity College Dublin); university_scholarships row 704 created. Linked source: 3112 (shared with record 978).$note$, 81, NULL, 'EUR', 'one_time', 'variable', NULL, '1-year tuition-fee reduction of EUR 2,000-EUR 5,000 for offer-holders on full-time taught postgraduate programmes in Engineering, Computer Science and Statistics, Natural Sciences and the MSc in Energy Science (batch deadlines 1 Feb / 15 Mar / 1 May 2027)', 'A one-year reduction of EUR 2,000-EUR 5,000 applied to the tuition fees of a full-time taught master''s programme - a partial discount, not full coverage.', 'No scholarship-level IELTS figure; English-language requirements belong to postgraduate programme admission.', $j$["Offer letter for a Postgraduate Taught Masters programme in the School of Engineering, the School of Computer Science and Statistics, the School of Natural Sciences, or the MSc in Energy Science", "Scholarship application form (linked from the E3 scholarships page) including a 200-word statement: 'How I will contribute to the E3 Initiative and provide Balanced Solutions for a Better World at Trinity College Dublin'"]$j$, NULL, NULL, $json$[{"batch": 1, "deadline": "2027-02-01", "announcement": "2027-03-01", "status": "open"}, {"batch": 2, "deadline": "2027-03-15", "announcement": "2027-04-15"}, {"batch": 3, "deadline": "2027-05-01", "announcement": "2027-05-31"}, {"pattern": "Applications after 1 May are assessed on a rolling basis depending on budget availability"}]$json$);

-- 980 — Hardiman Research Scholarships --------------------------------------------------------
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (980, 'Hardiman Research Scholarships (University of Galway)', 'University of Galway', 'Ireland', 'Full Tuition + Stipend', 0, 'The 2026 call is closed (it ran 1 December 2025 to 6 February 2026, 17:00 Irish Time, for a 1 September 2026 start). The application system normally re-opens in early December for the following September intake: expect the next round to open around December 2026 and close in early February 2027 - but those dates were not yet published when this record was verified, so no deadline_date is recorded. Use the time now to find and agree a supervisor: the supervisor form, your application and both academic references all share the same closing deadline.', NULL, 'not_published', NULL, NULL, $j$["PhD"]$j$, $j$["Full-time Structured PhD programmes across the University of Galway's research-postgraduate portfolio (Burren College of Art programmes are not eligible)"]$j$, $j$["High-achieving applicants of any nationality commencing a full-time Structured PhD (expected: first or upper second class honours primary degree or equivalent); not open to persons currently registered as PhD students or who already hold a PhD"]$j$, NULL, NULL, false, true, $desc$The Hardiman Research Scholarships are the University of Galway's flagship internal PhD scholarships: fully funded awards for students commencing a full-time Structured PhD at the university on 1 September. Each scholarship runs for four years and combines a stipend of EUR 25,000 per year with tuition fee cover for the four-year period (note the fine print: the package does not cover the student levy or provide a budget for consumables or travel). The university frames them for 'high-achieving individuals, with drive and passion, who have an appetite for the research world and creativity', and successful applicants are expected to hold a first or upper second class honours primary degree or equivalent. The process is supervisor-led and synchronised: you first find and nominate one supervisor through the university's Find a Supervisor service, your proposed supervisor submits a supervisor form, you submit the complete scholarship application (in English or Irish only, after reading the Applicant's Guide, which the university requires every applicant to read), and two academic references attesting to your suitability and potential for postgraduate research must also arrive - all by the same closing deadline (in the 2026 call: 6 February 2026 at 17:00 Irish Time, after applications opened on 1 December 2025; interviews followed in April 2026 and outcomes in late May 2026). There is no fee to apply for the scholarship itself (the separate PhD programme application carries a fee), and the number of scholarships varies from year to year with available funding. The 2026 round is closed; the FAQs state the application system normally re-opens in early December for the following September intake.$desc$, $req$You must be starting - not already in - a PhD: applications are not accepted from persons currently registered as PhD students or who previously were awarded a PhD, and scholarships are awarded only to those admitted to full-time Structured PhDs at the University of Galway (part-time study and Burren College of Art programmes are ineligible). Academically, successful applicants are expected to have a first or upper second class honours primary degree or equivalent, and you must meet the university's English language requirements for research-postgraduate entry. Practically, the supervisor is the long pole: identify and contact a potential supervisor well before the deadline (via Find a Supervisor), nominate exactly one, and make sure their supervisor form is submitted by the closing time - your complete application and your two academic references are due by the same deadline (in the 2026 call, 6 February at 17:00 Irish Time, with interviews in April and outcomes in late May). Read the Applicant's Guide before completing the form - the university makes this a stated requirement for all applicants - and note that while the scholarship application itself is free, the Structured PhD programme application carries a fee. Irish honours classifications do not map to one numeric GPA and English requirements sit in general entry requirements, so min_gpa/min_ielts are not recorded; the fetched pages also do not distinguish EU versus non-EU tuition-fee levels for the 'tuition fee covered' element, so confirm your exact fee position with the university when you apply.$req$, 'https://www.universityofgalway.ie/hardiman-scholarships/', 'https://www.universityofgalway.ie/hardiman-scholarships/', 'https://www.universityofgalway.ie/hardiman-scholarships/', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-28 (enrichment batch 22) from the University of Galway's official Hardiman Research Scholarships pages fetched the same day - the overview (2026 applications closed and all applicants informed; for students starting their PhD on 1 September 2026; fully funded for four years with a stipend of EUR 25,000 p.a. plus tuition fee covered; Structured PhD across the university's research-postgraduate programmes; three-step process: nominate one supervisor with the supervisor form, submit a complete application, and two academic references, all by 6 February 2026 17:00 Irish Time, applications in English or Irish only and the Applicant's Guide must be read first; FAQs: the system normally re-opens in early December for the following September intake, current PhD students and PhD holders are ineligible, full-time Structured PhDs only, Burren College of Art ineligible, no fee for the scholarship application though the PhD programme application has one, the number of scholarships varies by year, and the package does not cover the student levy or consumables/travel), the eligibility page (successful applicants expected to have a first or upper second class honours primary degree or equivalent; no applications from persons currently registered as PhD students or previously awarded a PhD; English language requirements per the Global Galway entry-requirements pages), and the timeline page (2026 call: applications open 1 December 2025, close 6 February 2026 17:00 Irish Time, interviews 16-27 April 2026, outcome late May 2026, scholarship begins 1 September 2026; timings indicative and may be subject to change). Award stored as 25000 (EUR, 'year', 'fixed') for the published stipend, with tuition-fee cover stated in the funding text; amount_usd_value 0 (non-USD); the fetched pages do not distinguish EU/non-EU fee levels for the tuition element, so no claim is encoded either way. deadline_date NULL/'not_published' with status 'upcoming': the 2026 call has closed and the next call's dated window (expected early December 2026 to February 2027 per the FAQ pattern) was not yet published. min_gpa/min_ielts NULL. university_id 283 (University of Galway); university_scholarships row 705 created. Linked source: 3113.$note$, 283, 25000, 'EUR', 'year', 'fixed', NULL, 'Fully funded 4-year Structured PhD: stipend EUR 25,000 per year plus tuition fee covered for the four-year period (student levy and consumables/travel not covered)', 'Tuition fee covered for four years alongside the EUR 25,000 annual stipend; the scheme pages read do not distinguish EU and non-EU fee levels - confirm your fee category with the university.', 'University of Galway research-postgraduate English language requirements apply (see Global Galway entry requirements); no scholarship-specific IELTS figure.', $j$["Read the current Applicant's Guide on the Hardiman webpage before applying (stated requirement for all applicants)", "One nominated supervisor, who submits the supervisor form by the closing deadline (find supervisors via the Find a Supervisor service)", "Complete Hardiman application form (English or Irish only) by the closing deadline", "Two academic references indicating suitability and potential for postgraduate research, received by the same deadline", "Structured PhD programme admission (separate application; a programme application fee applies)"]$j$, NULL, NULL, $json$[{"cycle": "2026 call (for 1 September 2026 start)", "opens": "2025-12-01", "deadline": "2026-02-06", "interviews": "2026-04-16 to 2026-04-27", "outcome": "2026-05 (late)", "status": "closed"}, {"pattern": "Annual: the application system normally re-opens in early December for the following September intake, closing in early February; supervisor form, application and references share one deadline"}]$json$);

