  (704, 81, 979, 'Postgraduate E3 Balanced Solutions for a Better World Scholarship', 'international_students', '1-year tuition-fee reduction of €2,000-€5,000 for offer-holders on full-time taught postgraduate programmes in Engineering, Computer Science & Statistics, Natural Sciences and MSc Energy Science (batch deadlines 1 Feb / 15 Mar / 1 May 2027)', '€5,000 one-year tuition-fee reduction (awards range €2,000-€5,000)', true, false, 'Academic achievement and potential to contribute to the E3 initiative (200-word statement required)', 'Hold an offer letter for a Postgraduate Taught Masters in Engineering, Computer Science & Statistics, Natural Sciences or MSc Energy Science', 'https://www.tcd.ie/e3/education/scholarships/', 'https://www.tcd.ie/e3/education/scholarships/', 'verified', now()),
  (705, 283, 980, 'Hardiman Research Scholarships (University of Galway)', 'international_students', 'Fully funded 4-year Structured PhD: stipend €25,000 per year plus tuition fee covered for four years', '€25,000/yr stipend + tuition fee covered (4 years)', true, true, 'Research excellence with a supervisor-supported proposal: nominate one supervisor, two academic references, interview stage', 'First or upper second class honours degree (or equivalent) expected; not open to current PhD students or PhD holders; full-time Structured PhD starting 1 September', 'https://www.universityofgalway.ie/hardiman-scholarships/', 'https://www.universityofgalway.ie/hardiman-scholarships/', 'verified', now());

