SELECT setval('scholarships_id_seq', GREATEST((SELECT MAX(id) FROM scholarships), 980), true),
       setval('sources_id_seq', GREATEST((SELECT MAX(id) FROM sources), 3113), true),
       setval('university_scholarships_id_seq', GREATEST((SELECT MAX(id) FROM university_scholarships), 705), true);

